create table public.moderation_reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete restrict, subject_type text not null, subject_id uuid not null, reason_code text not null, details text not null default '', status text not null default 'open', reviewer_id uuid references public.profiles(id) on delete set null, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), resolved_at timestamptz, constraint moderation_report_status check(status in ('open','assigned','resolved','dismissed')));
create table public.moderation_actions (id uuid primary key default gen_random_uuid(), report_id uuid references public.moderation_reports(id) on delete set null, subject_type text not null, subject_id uuid not null, actor_id uuid references public.profiles(id) on delete set null, action text not null, reason text not null default '', created_at timestamptz not null default timezone('utc',now()));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, request_id uuid, ip_hash text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default timezone('utc',now()), constraint audit_metadata_object check(jsonb_typeof(metadata)='object'));
create table public.admin_cases (id uuid primary key default gen_random_uuid(), report_id uuid references public.moderation_reports(id) on delete set null, case_type text not null, subject_type text, subject_id uuid, status text not null default 'open', priority smallint not null default 3, assignee_id uuid references public.profiles(id) on delete set null, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), closed_at timestamptz, constraint admin_case_status check(status in ('open','in_progress','resolved','closed')), constraint admin_case_priority check(priority between 1 and 5));
create index moderation_reports_queue_idx on public.moderation_reports(status,created_at); create index moderation_reports_reporter_idx on public.moderation_reports(reporter_id); create index moderation_actions_subject_idx on public.moderation_actions(subject_type,subject_id,created_at); create index audit_logs_entity_idx on public.audit_logs(entity_type,entity_id,created_at desc); create index audit_logs_actor_idx on public.audit_logs(actor_id,created_at desc); create index admin_cases_queue_idx on public.admin_cases(status,priority,created_at);
create trigger moderation_reports_set_updated_at before update on public.moderation_reports for each row execute function public.set_updated_at(); create trigger admin_cases_set_updated_at before update on public.admin_cases for each row execute function public.set_updated_at();
alter table public.moderation_reports enable row level security; alter table public.moderation_actions enable row level security; alter table public.audit_logs enable row level security; alter table public.admin_cases enable row level security;
create policy moderation_reports_read on public.moderation_reports for select to authenticated using(reporter_id=auth.uid() or public.has_permission('moderation.manage')); create policy moderation_reports_insert on public.moderation_reports for insert to authenticated with check(reporter_id=auth.uid()); create policy moderation_reports_update on public.moderation_reports for update to authenticated using(public.has_permission('moderation.manage')) with check(public.has_permission('moderation.manage'));
create policy moderation_actions_read on public.moderation_actions for select to authenticated using(public.has_permission('moderation.manage')); create policy moderation_actions_insert on public.moderation_actions for insert to authenticated with check(public.has_permission('moderation.manage'));
create policy audit_logs_read on public.audit_logs for select to authenticated using(public.has_permission('audit.read'));
create policy admin_cases_manage on public.admin_cases for all to authenticated using(public.has_permission('moderation.manage')) with check(public.has_permission('moderation.manage'));
